using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
public static partial class EmergencyLightingWorkbench {
 const string AssetsRoot="Assets/EmergencyDeconLighting";
 const string RigName="EmergencyDecon_ClinicalLighting";
 [MenuItem("Tools/RadCare/Emergency Lighting/Rebuild and Bake All Three Scenes")]
 public static void RebuildAll(){try{StartJob(0,2);}catch(Exception e){Fail(e);}}
 [MenuItem("Tools/RadCare/Emergency Lighting/Validate Current Baked Scene")]
 public static void ValidateCurrent(){try{ValidateNumerics(SceneManager.GetActiveScene());Debug.Log("Emergency lighting validation passed.");}catch(Exception e){Fail(e);}}
 static int jobIndex=-1,jobLast;static double finishAt;static string returnScene;
 static void Fail(Exception e){jobIndex=-1;baking=false;finishAt=0;File.WriteAllText(Out+".error",e.ToString());Debug.LogException(e);}
 static void StartJob(int first,int last){if(EditorApplication.isPlaying||Lightmapping.isRunning)throw new Exception("Edit mode without active bake required");Directory.CreateDirectory(Out);Directory.CreateDirectory("Documentation/EmergencyLighting/Before");Directory.CreateDirectory(AssetsRoot);AssetDatabase.Refresh();returnScene=SceneManager.GetActiveScene().path;
  for(int i=0;i<SceneManager.sceneCount;i++){var scene=SceneManager.GetSceneAt(i);if(scene.isDirty){if(!Scenes.Contains(scene.path))throw new Exception("Unrelated dirty scene: "+scene.path);EditorSceneManager.SaveScene(scene);}}
  foreach(var path in Scenes){string backup="Documentation/EmergencyLighting/Before/"+System.IO.Path.GetFileName(path);if(!File.Exists(backup))File.Copy(path,backup);}
  jobIndex=first;jobLast=last;BeginCurrentScene();
 }
 static LightingSettings Settings(){var path=AssetsRoot+"/EmergencyDecon_Clinical.lighting";var settings=AssetDatabase.LoadAssetAtPath<LightingSettings>(path);if(!settings){settings=new LightingSettings();AssetDatabase.CreateAsset(settings,path);}settings.bakedGI=true;settings.realtimeGI=false;settings.lightmapper=LightingSettings.Lightmapper.ProgressiveGPU;settings.lightmapResolution=24;settings.lightmapMaxSize=1024;settings.lightmapPadding=4;settings.directSampleCount=64;settings.indirectSampleCount=256;settings.environmentSampleCount=128;settings.maxBounces=3;settings.directionalityMode=LightmapsMode.CombinedDirectional;settings.mixedBakeMode=MixedLightingMode.IndirectOnly;settings.filteringMode=LightingSettings.FilterMode.Auto;settings.ao=false;settings.indirectScale=1;settings.albedoBoost=1;settings.lightProbeSampleCountMultiplier=2;EditorUtility.SetDirty(settings);return settings;}
 static void BeginCurrentScene(){if(jobIndex<0)return;var path=Scenes[jobIndex];var s=SceneManager.GetActiveScene();if(s.path!=path||SceneManager.sceneCount>1)s=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);File.WriteAllText(Out+"-status.txt","CONFIGURING "+s.name);Configure(s);EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);AssetDatabase.SaveAssets();bakeMessages.Clear();bakeLabel=s.name;baking=true;File.WriteAllText(Out+"-status.txt","BAKING "+s.name);if(!Lightmapping.BakeAsync()){baking=false;throw new Exception("Bake did not start for "+s.name);}}
 static GameObject Child(string name,Transform parent){var go=new GameObject(name);go.transform.SetParent(parent,false);return go;}
 static Material MaterialAsset(string name,Color baseColor,bool emission){string path=AssetsRoot+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=name};AssetDatabase.CreateAsset(m,path);}m.SetColor("_BaseColor",baseColor);m.SetFloat("_Metallic",0);m.SetFloat("_Smoothness",emission?.15f:.25f);if(emission){m.shader=Shader.Find("Universal Render Pipeline/Unlit");m.SetColor("_BaseColor",new Color(5f,4.88f,4.64f,1f));m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",new Color(1f,.92f,.81f)*1.2f);m.globalIlluminationFlags=MaterialGlobalIlluminationFlags.None;}EditorUtility.SetDirty(m);return m;}
 static void Configure(Scene s){var previous=s.GetRootGameObjects().FirstOrDefault(o=>o.name==RigName);if(previous)UnityEngine.Object.DestroyImmediate(previous);
  var changes=new List<string>();foreach(var l in All<Light>(s)){if(l.enabled){changes.Add("Legacy light disabled: "+PathOf(l.transform));l.enabled=false;}}
  // Exclude all interactive, XR and transparent renderers from static GI, even when inactive.
  foreach(var r in All<Renderer>(s)){string path=PathOf(r.transform);var mr=r as MeshRenderer;var mf=r.GetComponent<MeshFilter>();bool underTent=r.transform.root.name=="Tent";bool transparent=r.sharedMaterials.Any(m=>m&&(m.renderQueue>=3000||m.shader.name.Contains("Particles")));bool collapsed=Mathf.Abs(r.localToWorldMatrix.determinant)<1e-12f;bool gloves=path.Contains("Gloves");bool dynamic=!underTent||transparent||collapsed||gloves||r is SkinnedMeshRenderer||r is ParticleSystemRenderer;
   if(dynamic){var flags=GameObjectUtility.GetStaticEditorFlags(r.gameObject);if((flags&StaticEditorFlags.ContributeGI)!=0){GameObjectUtility.SetStaticEditorFlags(r.gameObject,flags&~StaticEditorFlags.ContributeGI);changes.Add("Probe-lit: "+path);}if(mr)mr.receiveGI=ReceiveGI.LightProbes;r.lightmapIndex=-1;r.lightProbeUsage=LightProbeUsage.BlendProbes;r.reflectionProbeUsage=ReflectionProbeUsage.BlendProbes;
    if(path.Contains("/Blood/")){r.shadowCastingMode=ShadowCastingMode.Off;var sc=r.transform.localScale;if(Mathf.Abs(sc.z)<1e-8f){sc.z=.0001f;r.transform.localScale=sc;changes.Add("Zero-thickness visual made finite: "+path);}}
   }else if(mr&&mf&&mf.sharedMesh){var mesh=mf.sharedMesh;var uv=mesh.uv2;bool valid=uv.Length==mesh.vertexCount&&uv.All(v=>Finite(v.x)&&Finite(v.y));if(valid){float dx=uv.Max(v=>v.x)-uv.Min(v=>v.x),dy=uv.Max(v=>v.y)-uv.Min(v=>v.y);valid=dx>1e-5f&&dy>1e-5f;}if(!valid){var copy=UnityEngine.Object.Instantiate(mesh);copy.name=mesh.name+"_LightmapUV";Unwrapping.GenerateSecondaryUVSet(copy);string mp=AssetsRoot+"/Mesh_"+AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(mesh))+"_"+mesh.GetInstanceID()+".asset";AssetDatabase.CreateAsset(copy,mp);mf.sharedMesh=copy;changes.Add("Generated UV2: "+path);}mr.receiveGI=ReceiveGI.Lightmaps;GameObjectUtility.SetStaticEditorFlags(r.gameObject,GameObjectUtility.GetStaticEditorFlags(r.gameObject)|StaticEditorFlags.ContributeGI);r.lightProbeUsage=LightProbeUsage.BlendProbes;r.reflectionProbeUsage=ReflectionProbeUsage.BlendProbes;}
  }
  Lightmapping.lightingSettings=Settings();Lightmapping.Clear();
  RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.38f,.41f,.44f);RenderSettings.ambientEquatorColor=new Color(.24f,.26f,.28f);RenderSettings.ambientGroundColor=new Color(.13f,.14f,.15f);RenderSettings.ambientIntensity=1;RenderSettings.reflectionIntensity=.75f;RenderSettings.reflectionBounces=1;RenderSettings.fog=false;
  var rig=new GameObject(RigName);SceneManager.MoveGameObjectToScene(rig,s);var housing=MaterialAsset("LED_Housing",new Color(.27f,.29f,.30f),false);var diffuser=MaterialAsset("LED_Diffuser",new Color(.87f,.89f,.88f),true);
  int number=0;foreach(float x in new[]{-1.45f,.85f,3.15f})foreach(float z in new[]{-2.55f,.55f}){
   number++;var panel=Child("Ceiling_LED_"+number,rig.transform);panel.transform.position=new Vector3(x,2.92f,z);
   var light=panel.AddComponent<Light>();light.type=LightType.Rectangle;light.lightmapBakeType=LightmapBakeType.Baked;light.areaSize=new Vector2(1.6f,.40f);light.intensity=7.5f;light.range=7;light.color=Color.white;light.useColorTemperature=true;light.colorTemperature=5500;light.bounceIntensity=1;light.shadows=LightShadows.Soft;panel.transform.rotation=Quaternion.Euler(90,0,0);
   var fixture=GameObject.CreatePrimitive(PrimitiveType.Cube);fixture.name="Housing";fixture.transform.SetParent(rig.transform,false);fixture.transform.position=new Vector3(x,2.98f,z);fixture.transform.localScale=new Vector3(1.67f,.07f,.46f);UnityEngine.Object.DestroyImmediate(fixture.GetComponent<Collider>());fixture.GetComponent<Renderer>().sharedMaterial=housing;GameObjectUtility.SetStaticEditorFlags(fixture,StaticEditorFlags.ContributeGI|StaticEditorFlags.BatchingStatic);
   var face=GameObject.CreatePrimitive(PrimitiveType.Cube);face.name="Diffuser";face.transform.SetParent(rig.transform,false);face.transform.position=new Vector3(x,2.934f,z);face.transform.localScale=new Vector3(1.59f,.018f,.39f);UnityEngine.Object.DestroyImmediate(face.GetComponent<Collider>());var fr=face.GetComponent<MeshRenderer>();fr.sharedMaterial=diffuser;fr.shadowCastingMode=ShadowCastingMode.Off;fr.receiveGI=ReceiveGI.LightProbes;
  }
  foreach(var item in new[]{new Vector3(-1.2f,2.5f,-2.7f),new Vector3(2.35f,2.5f,-.2f)}){var go=Child("Mixed_Task_Fill",rig.transform);go.transform.position=item;var light=go.AddComponent<Light>();light.type=LightType.Point;light.lightmapBakeType=LightmapBakeType.Mixed;light.intensity=1f;light.range=5.5f;light.color=Color.white;light.useColorTemperature=true;light.colorTemperature=5500;light.shadows=LightShadows.None;light.bounceIntensity=1;}
  var probeObject=Child("Interior_LightProbes",rig.transform);var probes=probeObject.AddComponent<LightProbeGroup>();var points=new List<Vector3>();foreach(float x in new[]{-2.3f,-1.2f,.3f,1.8f,3.8f})foreach(float z in new[]{-4f,-2.7f,-1f,.7f,2f})foreach(float y in new[]{.35f,1.15f,2.25f})points.Add(new Vector3(x,y,z));probes.probePositions=points.ToArray();
  var rp=Child("Interior_ReflectionProbe",rig.transform).AddComponent<ReflectionProbe>();rp.transform.position=new Vector3(.8f,1.5f,-1.1f);rp.mode=ReflectionProbeMode.Baked;rp.resolution=128;rp.hdr=true;rp.boxProjection=true;rp.size=new Vector3(7.5f,3.9f,7.4f);rp.center=new Vector3(0,.4f,0);rp.blendDistance=.6f;rp.intensity=.8f;rp.nearClipPlane=.1f;rp.farClipPlane=20;rp.clearFlags=ReflectionProbeClearFlags.Skybox;
  File.WriteAllText(Out+"/"+s.name+"-changes.txt",string.Join("\n",changes));
 }
 static void FinishCurrentScene(){var s=SceneManager.GetActiveScene();if(bakeMessages.Any(m=>m.Contains("Non finite")||m.Contains("invalid UV")))throw new Exception("Bake validation failed: "+string.Join("\n",bakeMessages));
  File.WriteAllText(Out+"-status.txt","VERIFYING "+s.name);var rp=All<ReflectionProbe>(s).Single(p=>p.name=="Interior_ReflectionProbe");string path=AssetsRoot+"/"+s.name+"_Reflection.exr";if(!Lightmapping.BakeReflectionProbe(rp,path))throw new Exception("Reflection bake failed");AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);rp.customBakedTexture=AssetDatabase.LoadAssetAtPath<Texture>(path);if(!rp.customBakedTexture)throw new Exception("Reflection texture missing");rp.mode=ReflectionProbeMode.Custom;
  // Bake already tetrahedralizes probes. A second manual pass is unnecessary for single-scene loading.
  EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);AssetDatabase.SaveAssets();Render(s,"after");RenderTreatment(s);int maps=LightmapSettings.lightmaps.Length;int probes=LightmapSettings.lightProbes?LightmapSettings.lightProbes.count:0;if(maps==0||probes<75)throw new Exception("Baked lighting/probes missing");
  ValidateNumerics(s);File.WriteAllText(Out+"/"+s.name+"-verified.txt","PASS\nBaked lightmaps: "+maps+"\nBaked probes: "+probes+"\nNonfinite / invalid UV messages: "+bakeMessages.Count+"\nReflection cubemap: "+path+"\nLighting settings: "+AssetDatabase.GetAssetPath(Lightmapping.lightingSettings));
  if(jobIndex<jobLast){jobIndex++;EditorApplication.delayCall+=BeginCurrentScene;}else{jobIndex=-1;File.WriteAllText(Out+"-status.txt","COMPLETE");if(!string.IsNullOrEmpty(returnScene)&&s.path!=returnScene)EditorSceneManager.OpenScene(returnScene,OpenSceneMode.Single);}
 }
 static void ValidateNumerics(Scene s){long samples=0;float peak=0;foreach(var lm in LightmapSettings.lightmaps){if(!lm.lightmapColor)throw new Exception("Missing lightmap color");foreach(var tex in new[]{lm.lightmapColor,lm.lightmapDir}.Where(t=>t!=null)){var rt=RenderTexture.GetTemporary(tex.width,tex.height,0,RenderTextureFormat.ARGBFloat,RenderTextureReadWrite.Linear);var old=RenderTexture.active;var cpu=new Texture2D(tex.width,tex.height,TextureFormat.RGBAFloat,false,true);try{Graphics.Blit(tex,rt);RenderTexture.active=rt;cpu.ReadPixels(new Rect(0,0,tex.width,tex.height),0,0);cpu.Apply();foreach(var c in cpu.GetPixels()){if(!Finite(c.r)||!Finite(c.g)||!Finite(c.b)||!Finite(c.a))throw new Exception("Non-finite final lightmap: "+tex.name);samples++;peak=Mathf.Max(peak,c.maxColorComponent);}}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(cpu);RenderTexture.ReleaseTemporary(rt);}}}if(peak<=0)throw new Exception("Black lightmaps");var sh=LightmapSettings.lightProbes.bakedProbes;foreach(var p in sh)for(int c=0;c<3;c++)for(int i=0;i<9;i++)if(!Finite(p[c,i]))throw new Exception("Non-finite probe coefficient");File.WriteAllText(Out+"/"+s.name+"-numeric.txt","PASS: finite lightmap pixels="+samples+"; finite probe coefficients="+(sh.Length*27)+"; max channel="+peak);}
 static void RenderTreatment(Scene s){var patient=All<Transform>(s).FirstOrDefault(t=>t.name=="Patient");if(!patient)return;var go=new GameObject("Treatment lighting preview");go.hideFlags=HideFlags.HideAndDontSave;SceneManager.MoveGameObjectToScene(go,s);var cam=go.AddComponent<Camera>();cam.enabled=false;cam.scene=s;cam.transform.position=patient.position+new Vector3(.65f,1.35f,.32f);cam.transform.LookAt(patient.position+new Vector3(.05f,.1f,.32f),Vector3.back);cam.orthographic=true;cam.orthographicSize=1.13f;cam.nearClipPlane=.03f;cam.farClipPlane=30;cam.GetUniversalAdditionalCameraData().allowXRRendering=false;var rt=new RenderTexture(1400,1100,24);rt.Create();var old=RenderTexture.active;var tex=new Texture2D(1400,1100,TextureFormat.RGB24,false);try{RenderPipeline.SubmitRenderRequest(cam,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1400,1100),0,0);tex.Apply();File.WriteAllBytes(Out+"/"+s.name+"-treatment.png",tex.EncodeToPNG());}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
}
